extern vec4 glowColor;

vec4 effect(vec4 color, Image texture, vec2 texture_coords, vec2 screen_coords) {
    vec2 uv = texture_coords - 0.5;

    // Improved Rounded Box SDF to eliminate "X" artifact
    // Box half-size 0.25, Corner radius is handled by the distance field nature
    vec2 d = abs(uv) - 0.2;
    float dist = length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);

    // Smooth falloff from the edge of the box
    // 0.0 is the edge of the box, 0.3 is the fade out distance
    float alpha = 1.0 - smoothstep(0.0, 0.3, dist);

    // Sharper falloff to reduce "large area" feel
    alpha = pow(alpha, 2.0);

    return glowColor * alpha;
}

vec4 effect(vec4 color, Image texture, vec2 texture_coords, vec2 screen_coords) {
    vec4 texcolor = Texel(texture, texture_coords);
    if (texcolor.a == 0.0) discard;
    return color;
}

extern number time;
extern number scale;

// Precision-safe scalar hash. The old sin(dot(...)) hash multiplied a
// large trigonometric result by 43758, which becomes blocky on fragment
// hardware with reduced float precision. This version keeps coordinates
// bounded and uses only small fract/dot operations.
float hash12(vec2 p) {
    p = mod(p, 71.0);
    vec3 p3 = fract(vec3(p.x, p.y, p.x) * 0.1031);
    p3 += dot(p3, vec3(p3.y, p3.z, p3.x) + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

float valueNoise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);
    float a = hash12(i);
    float b = hash12(i + vec2(1.0, 0.0));
    float c = hash12(i + vec2(0.0, 1.0));
    float d = hash12(i + vec2(1.0, 1.0));
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(a, b, u.x)
        + (c - a) * u.y * (1.0 - u.x)
        + (d - b) * u.x * u.y;
}

float fbm(vec2 st) {
    float value = 0.0;
    float amplitude = 0.5;
    for (int i = 0; i < 4; i++) {
        value += amplitude * valueNoise(st);
        st *= 2.0;
        amplitude *= 0.5;
    }
    return value;
}

vec4 effect(vec4 color, Image texture, vec2 texture_coords, vec2 screen_coords) {
    // Preserve the original three-pixel cloudy/pixelated appearance.
    float pixelSize = max(1.0, 3.0 * scale);
    vec2 samplePx = floor(screen_coords / pixelSize);
    vec2 uv = samplePx / 200.0;

    // A cosine loop follows nearly the same slow drift as the old linear
    // timer for its first half, then returns smoothly without ever sending
    // large time values to the shader.
    const float TAU = 6.28318530718;
    float phase = time * (TAU / 100.0);
    float drift = 0.5 - 0.5 * cos(phase);
    uv += vec2(drift, drift * 0.5);
    float n = fbm(uv);
    float n2 = fbm(uv + vec2(n * 2.0, n * 0.5) - vec2(drift * 2.5));
    float finalNoise = mix(n, n2, 0.6);

    // Original upgrade-screen palette.

    vec3 colDeep = vec3(0.10, 0.08, 0.14); // Darker than #2e222f (Abyss)
    vec3 colBase = vec3(0.18, 0.13, 0.18); // #2e222f (UI Dark)
    vec3 colMid  = vec3(0.24, 0.21, 0.28); // #3e3546 (UI Light)
    vec3 colHigh = vec3(0.35, 0.25, 0.35); // Faint Highlight

    vec3 col = colDeep;

    // Smooth mixing based on noise height.
    col = mix(col, colBase, smoothstep(0.2, 0.5, finalNoise));
    col = mix(col, colMid,  smoothstep(0.5, 0.7, finalNoise));
    col = mix(col, colHigh, smoothstep(0.7, 1.0, finalNoise));

    // Darken edges to focus on the upgrade tree.
    vec2 vUV = screen_coords / love_ScreenSize.xy;
    float vignette = 1.0 - smoothstep(0.5, 1.5, length(vUV - 0.5) * 1.5);
    col *= vignette;

    // A one-LSB interleaved dither prevents visible color bands on 8/10-bit
    // output without introducing another grid into the cloud field.
    float dither = fract(52.9829189
        * fract(dot(screen_coords, vec2(0.06711056, 0.00583715)))) - 0.5;
    col += vec3(dither * (1.0 / 255.0));

    return vec4(clamp(col, vec3(0.0), vec3(1.0)), 1.0) * color;
}
